<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\News;use Illuminate\Http\Request;use Illuminate\Support\Str;class NewsController extends Controller{public function index(){return view('admin.news.index',['items'=>News::latest()->paginate(20)]);}public function create(){return view('admin.news.form',['item'=>new News]);}public function store(Request $r){News::create($this->data($r));return redirect()->route('admin.news.index')->with('ok','Новость создана');}public function edit(News $news){return view('admin.news.form',['item'=>$news]);}public function update(Request $r,News $news){$news->update($this->data($r));return redirect()->route('admin.news.index')->with('ok','Новость обновлена');}public function destroy(News $news){$news->delete();return back()->with('ok','Новость удалена');}private function data(Request $r):array{$d=$r->validate(['title'=>'required|max:255','excerpt'=>'nullable','content'=>'nullable','published_at'=>'nullable|date']);$d['slug']=Str::slug($r->input('slug')?:$d['title']);$d['is_published']=$r->boolean('is_published');return $d;}}